static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    KvCachedChatBatchAttentionCustomTilingData tiling;

    const gert::Shape* q_shape = context->GetInputShape(0);
    // Expect shape: [B, qLen, D]
    uint32_t batch = static_cast<uint32_t>(q_shape->GetOriginShape().GetDim(0));
    uint32_t qLen   = static_cast<uint32_t>(q_shape->GetOriginShape().GetDim(1));
    uint32_t dModel = static_cast<uint32_t>(q_shape->GetOriginShape().GetDim(2));

    const gert::Shape* k_shape = context->GetInputShape(1);
    // Expect shape: [B, kvLen, D]
    uint32_t kvLen  = static_cast<uint32_t>(k_shape->GetOriginShape().GetDim(1));

    // Simple tiling setup
    uint32_t tileD  = 256;  // vector tile along feature dim
    uint32_t tileKV = 64;   // rows of K/V per iteration

    float invSqrtD = 1.0f / std::sqrt(static_cast<float>(dModel));

    // Set block dim: each block handles one batch if possible
    uint32_t blockDim = batch > 0 ? batch : 1;
    context->SetBlockDim(blockDim);

    tiling.set_batch(batch);
    tiling.set_qLen(qLen);
    tiling.set_kvLen(kvLen);
    tiling.set_dModel(dModel);
    tiling.set_tileD(tileD);
    tiling.set_tileKV(tileKV);
    tiling.set_invSqrtD(invSqrtD);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
